<?php
declare(strict_types=1);
require (dirname(__DIR__, 5) . '/app/Bootstrap/bootstrap.php');MarketplaceModule::boot();require_once (dirname(__DIR__, 5) . '/app/Modules/Marketplace/Services/MarketplaceOrdersService.php');header('Cache-Control: no-store, private');
try{Workspace::require(Workspace::MARKETPLACE);$activeStoreId=(string)($_GET['store']??'');$ordersPage=(new MarketplaceOrdersService(Database::pdo()))->listing($activeStoreId,$_GET,($_GET['format']??'')==='csv');$activeStore=$ordersPage['store'];foreach((new MarketplaceService())->getStores(false) as $s)if($s['id']===$activeStoreId){$activeStore=$s;break;}
if(($_GET['format']??'')==='csv'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="pesanan-toko.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['Toko','Tanggal','Kode Pesanan','Nilai Pesanan','Unit','Kurir','Resi','Status']);$safe=static fn($v)=>preg_match('/^[=+\-@\t\r]/',(string)$v)?"'".$v:$v;foreach($ordersPage['rows'] as $r)fputcsv($out,array_map($safe,[$activeStore['store_name'],$r['date'],"'".$r['id'],$r['amount'],$r['quantity'],$r['courier'],"'".$r['tracking'],$r['status']]));fclose($out);exit;}
header('Content-Type: text/html; charset=utf-8');require (dirname(__DIR__, 5) . '/app/Modules/Marketplace/Views/marketplace_orders.php');
}catch(Throwable $e){http_response_code($e instanceof InvalidArgumentException?422:403);echo htmlspecialchars($e instanceof InvalidArgumentException?$e->getMessage():'Pesanan belum dapat dimuat. Periksa akses toko.',ENT_QUOTES,'UTF-8');}
